INSERT INTO "settings" ("key", "value") VALUES
  ('salon', '{"name":"BLUSH","tagline":"Nail care • Art • Extensions","phone":"","whatsapp":"","email":"","address":"","mapEmbedUrl":"","mapLink":"","instagram":"","googleReviewsUrl":"","announcement":"Bridal & festive season — reserve your date early"}'::jsonb),
  ('booking', '{"slotStepMin":30,"minLeadMin":120,"maxAdvanceDays":45,"cancelWindowHours":24,"autoConfirmInstant":true,"quoteValidHours":24}'::jsonb),
  ('policies', '{"version":"2026-11-15","privacy":"We collect your name and mobile number (and optionally email, nail preferences and inspiration photos) only to manage your appointments and contact you about them.\n\nWe do not sell or share your data with advertisers. Messages are sent through WhatsApp/SMS providers on our behalf.\n\nYou can update your details or delete your account at any time from My Account → Profile. Deleted accounts are anonymised; appointment records needed for accounts/tax are kept without your personal details.\n\nQuestions or complaints: contact us using the details on the Contact page.","cancellation":"You can cancel or ask to reschedule from My Account up to 24 hours before your appointment.\n\nWithin 24 hours, please message us on WhatsApp. Repeated no-shows may require an advance deposit for future bookings.\n\nFinal prices for extensions and nail art depend on length, design and products, and are confirmed before your service begins."}'::jsonb)
